k-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":325,\"sizeSlug\":\"large\",\"linkDestination\":\"custom\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><a href=\"https://demo.athemes.com/botiga/product-category/cosmetics/\"><img src=\"https://matchyx2.shop/wp-content/uploads/2021/07/Rectangle-581-1.jpg\" alt=\"\" class=\"wp-image-325\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><a style=\"text-decoration:none;\" href=\"https://demo.athemes.com/botiga/product-category/cosmetics/\" data-type=\"URL\" data-id=\"https://demo.athemes.com/botiga/product-category/cosmetics/\">Makeup</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":323,\"sizeSlug\":\"large\",\"linkDestination\":\"custom\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><a href=\"https://demo.athemes.com/botiga/product-category/cosmetics/\"><img src=\"https://matchyx2.shop/wp-content/uploads/2021/07/Rectangle-582-1.jpg\" alt=\"\" class=\"wp-image-323\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><a style=\"text-decoration:none;\" href=\"https://demo.athemes.com/botiga/product-category/cosmetics/\" data-type=\"URL\" data-id=\"https://demo.athemes.com/botiga/product-category/cosmetics/\">Lipstick</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":326,\"sizeSlug\":\"large\",\"linkDestination\":\"custom\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><a href=\"https://demo.athemes.com/botiga/product-category/cosmetics/\"><img src=\"https://matchyx2.shop/wp-content/uploads/2021/07/Rectangle-583-1.jpg\" alt=\"\" class=\"wp-image-326\"/></a></figure>\n<!-- /